+    ubFormer_ = GetUbFormer(inputTypeBitSize, outputTypeBitSize);
+    OP_CHECK_IF(ubFormer_ == 0,
                 OP_LOGE_FOR_INVALID_VALUE(context_->GetNodeName(), "ubSize", std::to_string(ubSize_), "greater than 0"),
