@@ -377,72 +330,11 @@ ge::graphStatus CastTiling::DoOpTiling()
                                           std::to_string(coreNum) + "," + std::to_string(coreNum_),
                                           "in the range [1, sys_core_num]"),
                 return ge::GRAPH_FAILED);
